-- Migration 0001: Initial schema with versioning and audit log
CREATE TABLE IF NOT EXISTS schema_version (
    version INTEGER PRIMARY KEY,
    applied_at_utc TEXT NOT NULL,
    hash TEXT NOT NULL
);

CREATE VIEW IF NOT EXISTS expense_breakdowns AS
SELECT e.id AS expense_id, e.category, e.amount, e.project_id, e.fund_id, e.date
FROM expenses e;

CREATE TABLE IF NOT EXISTS p2p_page_donations (
    page_id     INTEGER NOT NULL REFERENCES p2p_pages(id) ON DELETE CASCADE,
    donation_id INTEGER NOT NULL REFERENCES donations(id) ON DELETE CASCADE,
    PRIMARY KEY (page_id, donation_id)
);

CREATE TRIGGER IF NOT EXISTS trg_workflow_events_v2_no_delete
BEFORE DELETE ON workflow_events_v2
FOR EACH ROW
BEGIN
    SELECT RAISE(ABORT, 'workflow_events_v2 is append-only; DELETE is not allowed');
END;

-- 0019_external_comms_authorization.sql
-- Add explicit user-level authorization controls and immutable authorization records

ALTER TABLE users ADD COLUMN can_authorize_external_comms INTEGER NOT NULL DEFAULT 0;

UPDATE users
SET can_authorize_external_comms = 1
WHERE lower(role) = 'admin';

